In CT 105 on proxmox: cd /tmp && curl -sfL -A 'hatbot-sysadmin/1.0' 'https://api.modrinth.com/v2/project/chunky/version?loaders=%5B%22fabric%22%5D&game_versions=%5B%2226.3%22%5D' -o chunky.json && python3 -c '
import json;v=json.load(open("/tmp/chunky.json"))
for x in v[:3]: print(x["version_number"],x["date_published"][:10],x["game_versions"],x["dependencies"],[(f["filename"],f["size"],f["hashes"]["sha512"][:16],f["url"]) for f in x["files"]])'

